-- targets: c38
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._checklist_templates_audit()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  NEW.updated_by := auth.uid();
  IF NEW.archived_at IS NULL THEN
    NEW.archived_by := NULL;
  ELSIF NEW.archived_at IS NOT NULL THEN
    NEW.archived_by := auth.uid();
  ELSE
    NEW.archived_by := OLD.archived_by;
  END IF;
  RETURN NEW;
END
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public._checklist_templates_audit()'::regprocedure) LIKE '%ELSIF NEW.archived_at IS NOT NULL%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('no transition guard') AS mutation;
